using System;using System.Threading.Tasks;using CTXD.Client.Features.FirstPlayable;using CTXD.Client.Networking;using UnityEngine;using UnityEngine.UI;
namespace CTXD.Client.Features.Activity { public sealed class LevelExpActivityPanel:MonoBehaviour { ApiClient _api;Action<string> _status;RectTransform _window;public static LevelExpActivityPanel Open(RectTransform host,ApiClient api,Action<string> status){var go=new GameObject("LevelExpActivityPanel");go.transform.SetParent(host,false);var p=go.AddComponent<LevelExpActivityPanel>();p._api=api;p._status=status;p.Build();_=p.Refresh();return p;}void Build(){var b=LegacyUiFactory.Panel(transform,"LevelExpBlocker",Vector2.zero,Vector2.one,new Color(0,0,0,.8f));_window=LegacyUiFactory.PixelPanel(b,"LevelExpWindow",380,190,520,300,new Color(.055f,.035f,.018f,1));}async Task Refresh(){try{var v=await _api.GetLevelExpActivityAsync();LegacyUiFactory.DestroyChildren(_window);LegacyUiFactory.PixelLabel(_window,"LEVEL GROWTH EVENT",22,TextAnchor.MiddleCenter,new Color(1,.8f,.3f),100,15,320,35);LegacyUiFactory.PixelButton(_window,"Close",430,18,65,27,()=>Destroy(gameObject));LegacyUiFactory.PixelLabel(_window,"Start "+v.startLevel.ToString("0.000")+"  Current "+v.currentLevel.ToString("0.000"),16,TextAnchor.MiddleCenter,Color.white,55,80,410,28);LegacyUiFactory.PixelLabel(_window,"Current reward EXP: "+v.rewardExp,16,TextAnchor.MiddleCenter,new Color(.9f,.8f,.55f),55,120,410,28);if(v.rewardAvailable)LegacyUiFactory.PixelButton(_window,"Claim",185,180,150,38,async()=>{try{var r=await _api.ClaimLevelExpActivityAsync();_status("Level event EXP +"+r.addedExp);await Refresh();}catch(Exception ex){_status(ex.Message);}});}catch(Exception ex){_status(ex.Message);Destroy(gameObject);}}} }
